local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["f60137b80dee7841"] = { "Venite a me, figli miei!", "." },
  ["f60d0f3d24ab7934"] = { "Quei progetti si pagano in ossa: LE TUE OSSA!", "." },
  ["f612be82cb7bbf66"] = { "Certo, {name}.\n\nGli avventurieri che l'Alba considera amichevoli devono consegnare in totale 60 insegne per accedere agli oggetti superiori. Per accedere a oggetti di potere ancora maggiore, dovrebbero consegnarne in totale 220.\n\nDevo ammettere che il prezzo è piuttosto alto per gli avventurieri che l'Alba non tiene in grande considerazione.", "." },
  ["f618fd5e9d49fd2b"] = { "Throm'ka, {class}. Tutto il materiale bellico è negli ultimi preparativi e viene spedito a ⟦Silithus=Silitus⟧. Le ultime consegne dovrebbero arrivare in meno di un giorno. Con l'equipaggiamento pronto e le nostre forze schierate, non resterà che aspettare che qualcuno suoni il gong sull'Altare dello Scarabeo, che dovrebbe aprire le porte di ⟦Ahn'Qiraj=Ahn'qiraj⟧ e dare inizio alla guerra.\n\nLok'tar Ogar!", "." },
  ["f61c02cfa670c6c5"] = { "%s accetta le reliquie da {name}.", "." },
  ["f61d2089c28bf25e"] = { "Dobbiamo eliminare gli elfi e la loro codarda ⟦Alliance=Alleanza⟧ dalla ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Va' all'Hall of the Brave nella ⟦Valley of Honor=Valle dell'Onore⟧ e parla con Brakgul Deathbringer, se hai la stoffa per aiutare l'⟦Horde=Orda⟧.", "." },
  ["f620831b08c56ce5"] = { "Farò del mio meglio, Vaelan.", "." },
  ["f62182ccd203035b"] = { "Senti un po', se non mi parli dell'incendio...", "." },
  ["f625eff5b518454d"] = { "Che lo spirito di Isha Awak ti dia forza, {name}.", "." },
  ["f63889c70ebd3c4b"] = { "La ⟦Coldtooth Mine=Miniera di Dentefreddo⟧ si trova in territorio dell'⟦Horde=Orda⟧, sulle montagne a nord del ⟦Frostwolf Graveyard=Cimitero dei Lupi Bianchi⟧.\n\nÈ controllata dall'⟦Alliance=Alleanza⟧.", "." },
  ["f639dacbbbd773cf"] = { "%s legge dalle tavolette. Suoni sconosciuti, mai uditi, ti scorrono nella coscienza.", "." },
  ["f639fde295d16043"] = { "Arriva un momento in cui la vita che conosciamo non basta più. Ci sentiamo in trappola e cerchiamo risposte, e troviamo la speranza che arde nei luoghi oscuri.\n\nSolo allora, {name}, muoviamo i primi passi verso la libertà.", "." },
  ["f6404eaceb0e4c80"] = { "Hai fatto bene, {name}. Continua la tua ricerca della conoscenza, e ricorda la storia che hai imparato.", "." },
  ["f64128a29785627b"] = { "Bisogna fare attenzione a non danneggiare l'esemplare...", "." },
  ["f64af4a53ee70a4c"] = { "Il mio sogno è servire un giorno ai tuoi ordini, <padrone/padrona> {name}. Sempre che tu mi giudichi mai all'altezza di simili cose...", "." },
  ["f64cfee276a1a590"] = { "La tua sfida è fallita!", "." },
  ["f653239efcfa4c0e"] = { "Dov'è l'acqua, Emma? Prendi l'acqua, Emma? Se non fosse per me, quella gente non saprebbe nemmeno che aspetto ha l'acqua.", "." },
  ["f655cb5b7f756ef3"] = { "⟦Razorfen Kraul=Gallerie di Lamaspina⟧", "." },
  ["f662e0d07115b46c"] = { "TRAFIGGETELI, SOLDATI!", "." },
  ["f662e235a69ab910"] = { "Ottieni una tessera d'accesso di livello superiore", "." },
  ["f677deaa0a786e8c"] = { "Allora perché sei qui? Cosa dovremmo fare, se non c'è speranza?", "." },
  ["f679881a04edb4f4"] = { "Così mi piace.", "." },
  ["f681118120d19ae8"] = { "Ben fatto!", "." },
  ["f689a251bac256b3"] = { "Noi difendiamo. Noi resistiamo. Noi mostriamo che siamo una cosa sola. Uniti. Noi distruggiamo. Il loro dio cadrà.", "." },
  ["f698d53141ed488c"] = { "L'erbalismo richiede un tocco delicato che pochi sanno insegnare come Malorne. Cercalo a est della locanda di Dolanaar.", "." },
  ["f6a9cc2c85cdf94f"] = { "A cosa mai potrebbe servirti una banca? E va bene, dovrai attraversare le ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧, a sud di Brill. In fondo c'è una serie di ascensori che scendono a ⟦Undercity=Sepulcra⟧. Quando arrivi, ferma uno di quei goffi Abomini che chiamano Undercity Guardian e chiedigli indicazioni migliori.", "." },
  ["f6af93b2afd17be7"] = { "Non mettere alla prova la mia pazienza, mortale.", "." },
  ["f6b15c4397c7d0db"] = { "La Stormpike Aid Station è stata presa dall'⟦Alliance=Alleanza⟧!", "." },
  ["f6b27937501fb9b7"] = { "Sei libero, Dughal! Vattene da qui!", "." },
  ["f6b4bb520ca40e3b"] = { "Che cos'è questa storia? Vuoi rovinarmi la reputazione? Io non insegno ai novellini, <bello/bella>. Va' a parlare con Milla Fairancora alla ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus.", "." },
  ["f6c11262f99859b3"] = { "Che vuoi? Sarei molto più felice lassù nei cieli che a terra a chiacchierare con <un/una> {race}, in questo momento.\n\nPazienza, non si può avere tutto.", "." },
  ["f6c667cba86b3630"] = { "Trova la Red Canyon Mining a nord-est del lago nella ⟦Valley of Honor=Valle dell'Onore⟧. Lì parla con Makaru.", "." },
  ["f6d1a86dd7e71952"] = { "L'ultima volta che hanno attaccato, c'è stato un solo attacco. Non mi stupirei se stavolta ce ne fossero di più.", "." },
  ["f6da7e04dfb61158"] = { "Non so cosa ci mettano in quei barili, ma va giù come il miele!", "." },
  ["f6db50c33f13e81b"] = { "Ecco che passa un'anima eroica.", "." },
  ["f6db5556f1b6fa6f"] = { "Hai scoperto qualche indizio, {name}?", "." },
  ["f6dc37296504c662"] = { "Ti do il benvenuto, <fratello/sorella> <mio/mia>. Se sei qui per addestrarti, mi farà piacere addestrarti.\n\nPresto verrà il momento in cui il richiamo del ⟦Emerald Dream=Sogno di Smeraldo⟧ si impadronirà di te. Andrai in letargo per molti anni e camminerai tra le forme più pure. Sarà lì, e allora, che si svolgerà il tuo addestramento finale.", "." },
  ["f6de3a0e80d35628"] = { "Tanto da fare, tanto da fare! Dove se ne va il tempo?", "." },
  ["f6e3f75ac95dce5f"] = { "Alla lunga ricarica ci si deve abituare, ma non c'è niente di meglio per aprire uno scontro.", "." },
  ["f6ee09b0247875c3"] = { "Mmmh... SENTO ODORE DI CIBO!", "." },
  ["f6f5b95ae5b636a5"] = { "Ti porgo i miei cordiali saluti, {race}. Ti sei allontanat<o/a> parecchio dai sentieri battuti solo per parlare con qualcuno che vive in una caverna. Confido che ci sia una ragione per questa visita strana, eppure non imprevista. Sì?", "." },
  ["f6fddae86839a7b4"] = { "Manca ancora molto, {name}?", "." },
})
